import { readFile } from "node:fs/promises";
import path from "node:path";
import { UPLOAD_DIR, UPLOAD_NAME, UPLOAD_TYPES } from "@/lib/uploads";

/**
 * Serves admin-uploaded images from the persistent UPLOAD_DIR.
 * Only names generated by the upload route are accepted, which rules out
 * path traversal. Files are immutable (random names), so they cache forever.
 */
export async function GET(_req: Request, ctx: RouteContext<"/uploads/[file]">) {
  const { file } = await ctx.params;
  if (!UPLOAD_NAME.test(file)) return new Response("Not found", { status: 404 });
  try {
    const body = await readFile(path.join(UPLOAD_DIR, file));
    return new Response(new Uint8Array(body), {
      headers: {
        "Content-Type": UPLOAD_TYPES[file.split(".").pop()!],
        "Cache-Control": "public, max-age=31536000, immutable",
        "X-Content-Type-Options": "nosniff",
      },
    });
  } catch {
    return new Response("Not found", { status: 404 });
  }
}
